  img: ({ alt }) => alt ? <span>{alt}</span> : null,
  a: ({ href, children }) => href ? <a href={href} className="rounded font-medium underline decoration-foreground/30 underline-offset-4 transition-colors hover:decoration-foreground focus-visible:outline-2" {...(href.startsWith("http") ? { target: "_blank", rel: "noopener noreferrer" } : {})}>{children}</a> : <span>{children}</span>,
};

const plugins = [remarkGfm];

/** Reveals freshly delivered replies progressively; saved history and reduced-motion users get the full text at once. */
export const AssistantMessage = memo(function AssistantMessage({ content, animate = false, onProgress }: { content: string; animate?: boolean; onProgress?: () => void }) {
  const [shown, setShown] = useState(0);
  const [finished, setFinished] = useState(!animate);
  const progress = useRef(onProgress);
  useEffect(() => { progress.current = onProgress; }, [onProgress]);
  useEffect(() => {
    if (finished) return;
    let frame = 0;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) { frame = requestAnimationFrame(() => setFinished(true)); return () => cancelAnimationFrame(frame); }
    const rate = Math.max(0.06, content.length / 1600);
    let position = 0, last = performance.now();
    const step = (now: number) => {
      position += (now - last) * rate; last = now;
      let next = Math.min(content.length, Math.floor(position));
      while (next < content.length && next - Math.floor(position) < 12 && !/\s/.test(content[next - 1] ?? " ")) next++;
      setShown(next); progress.current?.();
      if (next >= content.length) setFinished(true); else frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
    return () => cancelAnimationFrame(frame);
  }, [content, finished]);
  return <div className="min-w-0 space-y-4 break-words text-[15px] leading-7 [&>*:first-child]:mt-0">
    <Markdown skipHtml urlTransform={safeLink} remarkPlugins={plugins} components={components}>{finished ? content : content.slice(0, shown)}</Markdown>
  </div>;
});
"use client";
import { useEffect, useRef, useState } from "react";
import { api, eventTypes, terminalStatuses, type Task, type TaskEvent } from "@/lib/task-api";

/** Run internals stay out of the conversation; people only see that the agent is working. */
function activityLabel(event: TaskEvent): string {
  const type = event.event_type;
  if (type === "test.finished") return "Running tests";
  if (type === "task.verified") return "Checking the result";
  if (type.startsWith("tool.") || type.startsWith("subagent.") || type.startsWith("task.step") || type === "task.plan.created") return "Working";
  return "Thinking";
}

export function ThinkingIndicator({ text = "Thinking" }: { text?: string }) {
  return <div role="status" aria-live="polite" className="flex items-center gap-2.5 py-1 text-[15px] leading-7 text-muted-foreground">
    <span className="thinking-orb shrink-0" aria-hidden="true" />
    <span>{text}</span>
  </div>;
}

/** Subscribes to the active run so the thread can settle the moment it finishes. Renders a single quiet indicator. */
export function TaskTurn({ taskId, onFinished }: { taskId: string; onFinished: () => void }) {
  const [task, setTask] = useState<Task | null>(null);
  const [label, setLabel] = useState("Thinking");
  const [unreachable, setUnreachable] = useState(false);
  const finishedCallback = useRef(onFinished);
  useEffect(() => { finishedCallback.current = onFinished; }, [onFinished]);
  useEffect(() => {
    const controller = new AbortController();
    let stream: EventSource | undefined;
    let inFlight = false;
    let terminal = false;
    let notified = false;
    let scheduled: ReturnType<typeof setTimeout> | undefined;
    async function load() {
      if (controller.signal.aborted || inFlight) return;
      inFlight = true;
      try {
        const result = await api<Task>(`/tasks/${taskId}`, { signal: controller.signal });
        if (controller.signal.aborted) return;
        setTask(result); setUnreachable(false);
        terminal = terminalStatuses.has(result.status);
        if (terminal) { stream?.close(); if (!notified) { notified = true; finishedCallback.current(); } }
      } catch { if (!controller.signal.aborted) setUnreachable(true); }
      finally { inFlight = false; }
    }
    if (typeof EventSource !== "undefined") {
      stream = new EventSource(`/api/v1/tasks/${taskId}/events?after=0`);
      const receive = (raw: Event) => {
        if (controller.signal.aborted) return;
        try {
          const event = JSON.parse((raw as MessageEvent<string>).data) as TaskEvent;
          if (event.task_id !== taskId) return;
          setLabel(activityLabel(event));
          if (!scheduled) scheduled = setTimeout(() => { scheduled = undefined; void load(); }, 300);
        } catch { /* Polling below keeps the state current. */ }
      };
      eventTypes.forEach((type) => stream?.addEventListener(type, receive));
      stream.addEventListener("session.closed", () => { stream?.close(); window.dispatchEvent(new Event("agentforge-session-expired")); });
    }
    void load();
    const timer = window.setInterval(() => { if (!terminal) void load(); }, 5000);
    return () => { controller.abort(); stream?.close(); window.clearInterval(timer); if (scheduled) clearTimeout(scheduled); };
  }, [taskId]);
  if (task && terminalStatuses.has(task.status)) return null;
  return <ThinkingIndicator text={task?.cancel_requested_at ? "Stopping" : unreachable ? "Reconnecting" : label} />;
}
