import type { Metadata } from "next";
import "./globals.css";
export const metadata: Metadata = {
  title: "AgentForge AI",
  description: "Your workspace for coding, research, and problem solving.",
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body className="font-sans antialiased">{children}</body>
    </html>
  );
}
import type { NextConfig } from "next";

const apiUrl = new URL(process.env.API_ORIGIN ?? "http://localhost:8000");
if (!["http:", "https:"].includes(apiUrl.protocol) || apiUrl.username || apiUrl.password || apiUrl.pathname !== "/" || apiUrl.search || apiUrl.hash) {
  throw new Error("API_ORIGIN must be an HTTP(S) origin without credentials, path, query or fragment.");
}
const nextConfig: NextConfig = {
  devIndicators: false,
  async rewrites() {
    return [
      {
        source: "/api/:path*",
        destination: `${apiUrl.origin}/api/:path*`,
      },
    ];
  },
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
};

export default nextConfig;
"use client";

import { useId, useState } from "react";
import { ChevronRight } from "lucide-react";

export function ThinkingBlock({ content, isThinking = false, onToggle }: { content: string; isThinking?: boolean; onToggle?: () => void }) {
  const id = useId();
  const [expanded, setExpanded] = useState<boolean | null>(null);
  const open = expanded ?? isThinking;

  if (!content.trim() && !isThinking) return null;

  return <div className="min-w-0 text-sm text-muted-foreground">
    <button
      type="button"
      aria-expanded={open}
      aria-controls={id}
      className="-ml-2 inline-flex min-h-11 max-w-full items-center gap-2 rounded-lg px-2 text-left outline-none transition-colors hover:bg-muted/60 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring motion-reduce:transition-none sm:min-h-9"
      onClick={() => { setExpanded(!open); onToggle?.(); }}
    >
      <ChevronRight className={`size-3.5 shrink-0 transition-transform motion-reduce:transition-none ${open ? "rotate-90" : ""}`} aria-hidden="true" />
      <span role="status">{isThinking ? "Thinking…" : "Thought process"}</span>
      {isThinking ? <span className="size-1.5 shrink-0 rounded-full bg-current motion-safe:animate-pulse" aria-hidden="true" /> : null}
    </button>
    <div id={id} hidden={!open} className="ml-1.5 border-l pl-4">
      <div className="max-h-64 overflow-y-auto overscroll-contain whitespace-pre-wrap pb-1 pr-3 leading-6 [overflow-wrap:anywhere]" tabIndex={open && content ? 0 : undefined} role="region" aria-label="Model thought process">
        {content}
      </div>
    </div>
  </div>;
}
/** Only leading provider thinking tags are metadata; examples in the answer stay untouched. */
export function splitAssistantContent(content: string, streaming = false) {
  let answer = content;
  const thoughts: string[] = [];
  while (answer.trimStart()) {
    const start = answer.trimStart();
    const opening = /^<(think|thinking)>/.exec(start);
    if (!opening) {
      if (streaming && ["<think>", "<thinking>"].some((tag) => tag.startsWith(start))) {
        return { answer: "", reasoning: thoughts.join("\n\n"), isThinking: true };
      }
      break;
    }
    const closing = `</${opening[1]}>`;
    const body = start.slice(opening[0].length);
    const end = body.indexOf(closing);
    if (end === -1) {
      // A closing tag can arrive over several chunks. Keep its partial syntax out of the UI.
      let text = body;
      if (streaming) {
        for (let length = closing.length - 1; length > 0; length--) {
          if (text.endsWith(closing.slice(0, length))) { text = text.slice(0, -length); break; }
        }
      }
      thoughts.push(text.trim());
      return { answer: "", reasoning: thoughts.join("\n\n"), isThinking: streaming };
    }
    thoughts.push(body.slice(0, end).trim());
    answer = body.slice(end + closing.length).trimStart();
  }
  return { answer, reasoning: thoughts.length ? thoughts.join("\n\n") : null, isThinking: false };
}

